import java.util.List;

public class LinkedListOpsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    /** Walks a chain without using student code, so a broken method cannot hide a bug. */
    static String rawValues(Node head) {
        StringBuilder sb = new StringBuilder("[");
        Node current = head;
        int guard = 0;
        while (current != null && guard < 50) {
            if (guard > 0) {
                sb.append(", ");
            }
            sb.append(current.value);
            current = current.next;
            guard++;
        }
        return sb.append("]").toString();
    }

    public static void main(String[] args) {
        check("length of an empty list", 0, LinkedListOps.length(null));
        check("toList of an empty list", "[]", String.valueOf(LinkedListOps.toList(null)));
        check("reversed of an empty list", null, LinkedListOps.reversed(null));

        Node one = LinkedListOps.append(null, 5);
        check("append onto null returns the new node", "[5]", rawValues(one));
        check("length of a one node list", 1, LinkedListOps.length(one));

        Node head = LinkedListOps.append(null, 1);
        Node returned = LinkedListOps.append(head, 2);
        check("append returns the same head object", true, head != null && head == returned);
        head = LinkedListOps.append(head, 3);
        head = LinkedListOps.append(head, 4);
        check("the chain was built in order", "[1, 2, 3, 4]", rawValues(head));
        check("length of the built chain", 4, LinkedListOps.length(head));
        check("toList of the built chain", "[1, 2, 3, 4]", String.valueOf(LinkedListOps.toList(head)));

        Node backwards = LinkedListOps.reversed(head);
        check("reversed walks the values backwards", "[4, 3, 2, 1]", rawValues(backwards));
        check("the original chain is untouched", "[1, 2, 3, 4]", rawValues(head));
        check("toList still sees the original", "[1, 2, 3, 4]", String.valueOf(LinkedListOps.toList(head)));

        boolean sharesNodes = false;
        Node outer = backwards;
        int guard = 0;
        while (outer != null && guard < 50) {
            Node inner = head;
            int innerGuard = 0;
            while (inner != null && innerGuard < 50) {
                if (outer == inner) {
                    sharesNodes = true;
                }
                inner = inner.next;
                innerGuard++;
            }
            outer = outer.next;
            guard++;
        }
        check("reversed built brand new nodes", false, sharesNodes);

        Node single = LinkedListOps.append(null, 9);
        check("reversed of a one node list", "[9]", rawValues(LinkedListOps.reversed(single)));

        List<Integer> values = LinkedListOps.toList(backwards);
        check("toList of the reversed chain", "[4, 3, 2, 1]", String.valueOf(values));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

